# Write your MySQL query statement below
SELECT MACHINE_ID, ROUND(AVG(DIFF), 3) processing_time FROM (SELECT ST.MACHINE_ID, ST.PROCESS_ID, EN.TIMESTAMP - ST.TIMESTAMP DIFF FROM (SELECT MACHINE_ID, PROCESS_ID, TIMESTAMP FROM ACTIVITY WHERE ACTIVITY_TYPE = 'start') ST INNER JOIN (SELECT MACHINE_ID, PROCESS_ID, TIMESTAMP FROM ACTIVITY WHERE ACTIVITY_TYPE = 'end') EN ON ST.MACHINE_ID = EN.MACHINE_ID AND ST.PROCESS_ID = EN.PROCESS_ID) SUB GROUP BY MACHINE_ID;